import { fileURLToPath } from 'node:url';
import { expect, test } from '@playwright/test';

// Compare the new SPA against PNGs of the OLD static site (e2e/baselines). snapshotPathTemplate
// points at that folder, so these are never regenerated by the tests. The new toolbar is
// absolutely positioned and absent from the old site, so it is hidden (equivalent to masking it,
// but it does not leave a coloured box that the baseline lacks).
const HIDE_TOOLBAR = fileURLToPath(new URL('../hide-toolbar.css', import.meta.url));
const THRESHOLD = { maxDiffPixelRatio: 0.01, threshold: 0.2 };

// The baselines were rendered on macOS; Linux (CI) has different system fonts, so text pixels
// would differ well beyond the threshold. Run locally on macOS, or force with E2E_VISUAL=1.
test.skip(
  process.platform !== 'darwin' && !process.env['E2E_VISUAL'],
  'old-site baselines are macOS renders; set E2E_VISUAL=1 to force',
);

const viewports = {
  desktop: { width: 1280, height: 900 },
  mobile: { width: 390, height: 844 },
} as const;

for (const [name, viewport] of Object.entries(viewports)) {
  test.describe(`visual ${name}`, () => {
    test.use({ viewport, deviceScaleFactor: 1 });

    for (const slug of ['meatloaf', 'elote-salad']) {
      test(`${slug} matches old site`, async ({ page }) => {
        const cat = slug === 'meatloaf' ? 'dinner/quick' : 'dinner/salad';
        await page.goto(`/routes/${cat}/${slug}`);
        await expect(page.getByTestId('recipe-title')).toBeVisible();
        // wait for the hero image so layout is final
        await page.waitForLoadState('networkidle');
        await expect(page).toHaveScreenshot(`${slug}-${name}.png`, {
          fullPage: true,
          animations: 'disabled',
          stylePath: HIDE_TOOLBAR,
          ...THRESHOLD,
        });
      });
    }

    test('index header and first rows match old site', async ({ page }) => {
      await page.goto('/');
      await expect(page.getByTestId('index-tree')).toBeVisible();
      await page.waitForLoadState('networkidle');
      // Rows differ further down (new site adds guga-rub and sorts alphabetically), so only
      // compare the top of the page. The baseline is cropped to the same region.
      const clip = { x: 0, y: 0, width: viewport.width, height: 225 };
      await expect(page).toHaveScreenshot(`index-${name}-clip.png`, {
        clip,
        animations: 'disabled',
        stylePath: HIDE_TOOLBAR,
        ...THRESHOLD,
      });
    });
  });
}
